// テンプレート文字列を Thymeleaf で描画してみる
// ここを変えてみよう:th:text を th:utext に / 在庫を 0 に / 商品を増やす
import java.time.LocalDate;
import java.util.*;
import org.thymeleaf.context.Context;
import org.thymeleaf.spring6.SpringTemplateEngine;
import org.thymeleaf.templateresolver.*;

record Item(String name, int price, int stock) {}

String template = """
    <p th:text="${message}">ここにメッセージ</p>
    <p th:utext="${message}">utext は HTML のまま</p>
    <p th:text="${#temporals.format(today, 'M月d日(E)')}">
      日付</p>
    <ul>
      <li th:each="item, st : ${items}"
          th:classappend="${st.odd} ? 'odd'">
        <span th:text="|${st.count}. ${item.name}|">名前</span>
        <span th:text="|${#numbers.formatInteger(
                item.price, 1, 'COMMA')}円|">価格</span>
        <b th:if="${item.stock == 0}">売り切れ</b>
        <span th:unless="${item.stock == 0}"
              th:text="|残り${item.stock}個|">在庫</span>
      </li>
    </ul>
    """;

var engine = new SpringTemplateEngine();
engine.setTemplateResolver(new StringTemplateResolver());

// Controller の Model の代わり。ここに入れた値を ${…} で読む
var ctx = new Context(Locale.JAPAN);
ctx.setVariable("message", "<b>本日</b>セール中");
ctx.setVariable("today", LocalDate.of(2026, 10, 11));
ctx.setVariable("items", List.of(
        new Item("ボールペン", 120, 12),
        new Item("<特価>ノート", 1500, 0),
        new Item("万年筆", 32000, 1)));

System.out.println(engine.process(template, ctx));

// Controller → Model → ビュー名 → Thymeleaf の流れを MockMvc で動かす
// ここを変えてみよう:Model に入れる値 / テンプレート / コンテキストパス
import java.util.*;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.*;
import static org.springframework.test.web.servlet
        .request.MockMvcRequestBuilders.*;
import org.thymeleaf.IEngineConfiguration;
import org.thymeleaf.spring6.SpringTemplateEngine;
import org.thymeleaf.spring6.view.ThymeleafViewResolver;
import org.thymeleaf.templateresolver.StringTemplateResolver;
import org.thymeleaf.templateresource.*;

record Item(int id, String name) {}

@Controller
class ItemController {
    @GetMapping("/items")
    String list(Model model) {
        model.addAttribute("items", List.of(
                new Item(1, "ボールペン"), new Item(2, "ノート")));
        return "items/list";   // ビュー名
    }
}

// 本物の templates/ フォルダの代わり(ファイル名 → 中身)
class Templates extends StringTemplateResolver {
    static final Map<String, String> FILES = Map.of(
        "fragments/layout", """
            <header th:fragment="header(title)">
              <a th:href="@{/}">Java商店</a>
              <b th:text="${title}">ページ名</b>
            </header>
            """,
        "items/list", """
            <header th:replace="~{fragments/layout :: header('商品一覧')}">
            </header>
            <ul>
              <li th:each="item : ${items}">
                <a th:href="@{/items/{id}(id=${item.id})}"
                   th:text="${item.name}">商品名</a>
              </li>
            </ul>
            """);

    @Override
    protected ITemplateResource computeTemplateResource(
            IEngineConfiguration conf, String owner, String name,
            Map<String, Object> attrs) {
        return new StringTemplateResource(FILES.get(name));
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        // Spring Boot が自動でやってくれる設定を手で書いている
        var engine = new SpringTemplateEngine();
        engine.setTemplateResolver(new Templates());
        var viewResolver = new ThymeleafViewResolver();
        viewResolver.setTemplateEngine(engine);
        viewResolver.setCharacterEncoding("UTF-8");

        MockMvc mvc = MockMvcBuilders
                .standaloneSetup(new ItemController())
                .setViewResolvers(viewResolver)
                .build();

        // アプリが /shop で公開されている想定(コンテキストパス)
        var res = mvc.perform(get("/shop/items").contextPath("/shop"))
                .andReturn().getResponse();
        System.out.println(res.getStatus() + " "
                + res.getContentType());
        System.out.println(res.getContentAsString());
    }
}

